section "tome-ashes-urhrok/data/general/npcs/aquatic-demon.lua"

t("Walrog", "ワルログ", "entity name")
t("demon", "デーモン", "entity type")
t("major", "上級デーモン", "entity subtype")
t("Walrog, the lord of Water, is #AQUAMARINE#fearsome#LAST# to behold. The water boils and writhes around him as if trying to escape, frothing steam making his form indistinct.  He does not seem surprised to see you.", "　水の支配者・ワルログだ。その姿は見るだに#AQUAMARINE#恐ろしい#LAST#。周囲では水がのたうつように沸き立ち、まるでワルログから逃れようとしている風だ。泡立つもやのせいではっきりとした姿は見えない。こちらの姿を目にしても驚く様子はない。", "_t")

